-- Initial schema and non-destructive adoption of the previous Hibernate-managed schema.
-- No table or business data is dropped. Conflicting duplicate SKUs fail migration for manual review.

create table if not exists app_users (id bigint generated by default as identity, role varchar(20) not null check ((role in ('USER','ADMIN','ORG'))), email varchar(255) not null unique, full_name varchar(255), password varchar(255) not null, primary key (id));
create table if not exists aria_logs (candidates_found integer not null, returned_to_active integer not null, total_scanned integer not null, urgent_items integer not null, analyzed_at timestamp(6) not null, id bigint generated by default as identity, details varchar(1000), primary key (id));
create table if not exists articles (word_count integer not null, id bigint generated by default as identity, parsed_at timestamp(6) not null, language varchar(20), title varchar(500), description varchar(1000), url varchar(1000), image_url varchar(2000), content varchar(10000), primary key (id));
create table if not exists audit_events (created_at timestamp(6) not null, id bigint generated by default as identity, action varchar(80) not null, resource varchar(120) not null, details varchar(2000) not null, actor varchar(255) not null, primary key (id));
create table if not exists cart_items (price_at_add_time numeric(12,2) not null, quantity integer not null, added_at timestamp(6) not null, id bigint generated by default as identity, product_id bigint not null, profile_id bigint, owner_email varchar(255), primary key (id));
create table if not exists discount_suggestions (suggested_percent integer not null, decided_at timestamp(6), id bigint generated by default as identity, product_id bigint not null, proposed_at timestamp(6) not null, status varchar(20) not null, reason varchar(500), decided_by varchar(255), primary key (id));
create table if not exists feedback (rating integer not null, resolved boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, message varchar(2000) not null, email varchar(255), primary key (id));
create table if not exists inventory_lots (active boolean not null, expiry_date date, initial_quantity integer not null, manufactured_at date, quantity integer not null, received_at date not null, unit_cost numeric(12,2) not null, id bigint generated by default as identity, product_id bigint not null, supplier_id bigint, lot_number varchar(80) not null, primary key (id), constraint uk_product_lot_number unique (product_id, lot_number));
create table if not exists order_allocations (quantity integer not null, id bigint generated by default as identity, lot_id bigint not null, order_id bigint not null, primary key (id));
create table if not exists order_items (price_per_unit numeric(12,2) not null, quantity integer not null, id bigint generated by default as identity, order_id bigint, product_id bigint not null, primary key (id));
create table if not exists orders (total_amount numeric(12,2) not null, created_at timestamp(6) not null, id bigint generated by default as identity, status varchar(20) not null, delivery_address varchar(500), owner_email varchar(255), primary key (id));
create table if not exists organization_verifications (id bigint generated by default as identity, reviewed_at timestamp(6), submitted_at timestamp(6) not null, user_id bigint not null unique, status varchar(32) not null, registration_number varchar(100) not null, organization_name varchar(160) not null, review_note varchar(500), reviewer_email varchar(255), primary key (id));
create table if not exists product_details (weight_kg numeric(8,2), id bigint generated by default as identity, product_id bigint not null unique, color varchar(50), size varchar(50), brand varchar(100), description_long TEXT, primary key (id));
create table if not exists product_photos (id bigint generated by default as identity, product_id bigint not null unique, content_type varchar(80) not null, file_name varchar(255), data oid not null, primary key (id));
create table if not exists products (archived boolean default false not null, discount_percent integer not null, expiry_date date, low_stock_threshold integer, market_avg_price numeric(12,2), quantity_on_hand integer not null, received_at date not null, sales_last30_days integer not null, unit_cost numeric(12,2), unit_price numeric(12,2), vat_percent integer, id bigint generated by default as identity, last_analyzed_at timestamp(6), lot_id bigint, version bigint default 0 not null, status varchar(20) not null check ((status in ('ACTIVE','CANDIDATE','RESERVED','TRANSFERRED','DISCOUNTED','SOCIAL','WRITTEN_OFF'))), unit varchar(20), barcode varchar(64), sku varchar(64) not null, dimensions varchar(100), category varchar(120), subcategory varchar(120), supplier varchar(120), image_url varchar(500), name varchar(500) not null, tags varchar(500), aria_reason varchar(1000), notes varchar(2000), primary key (id), constraint uk_product_sku unique (sku));
create table if not exists reviews (rating integer not null, created_at timestamp(6) not null, id bigint generated by default as identity, product_id bigint not null, author_name varchar(100) not null, comment TEXT not null, primary key (id));
create table if not exists social_offers (quantity_available integer not null, quantity_claimed integer not null, social_price numeric(12,2), valid_until date, claimed_at timestamp(6), created_at timestamp(6) not null, id bigint generated by default as identity, org_id bigint, product_id bigint not null, status varchar(20) not null, primary key (id));
create table if not exists suppliers (active boolean not null, id bigint generated by default as identity, contact varchar(160), name varchar(160) not null, notes varchar(1000), primary key (id));
create table if not exists transfer_lots (created_at timestamp(6) not null, id bigint generated by default as identity, state varchar(20) not null, partner varchar(120), note varchar(500), primary key (id));
create table if not exists transfer_records (quantity integer not null, unit_cost numeric(12,2), id bigint generated by default as identity, lot_id bigint not null, product_id bigint not null, transferred_at timestamp(6) not null, sku varchar(64) not null, partner varchar(120) not null, product_name varchar(500) not null, reason varchar(1000), primary key (id), constraint uk_transfer_record_lot_product unique (lot_id, product_id));
create table if not exists user_profiles (id bigint generated by default as identity, phone varchar(50), email varchar(100) not null unique, full_name varchar(100), address varchar(500), primary key (id));
create table if not exists wishlist_items (added_at timestamp(6) not null, id bigint generated by default as identity, product_id bigint not null, owner_email varchar(255), primary key (id));
alter table products add column if not exists archived boolean not null default false;
alter table products add column if not exists version bigint not null default 0;
alter table products add column if not exists barcode varchar(64);
alter table products add column if not exists vat_percent integer default 20;
alter table products add column if not exists unit varchar(20) default 'шт';
alter table products add column if not exists subcategory varchar(120);
alter table products add column if not exists tags varchar(500);
alter table products add column if not exists supplier varchar(120);
alter table products add column if not exists notes varchar(2000);
alter table products add column if not exists dimensions varchar(100);
alter table products add column if not exists low_stock_threshold integer default 5;
create unique index if not exists uk_product_sku on products(sku);
create index if not exists ix_lot_product_expiry on inventory_lots(product_id,expiry_date);
create index if not exists ix_audit_time on audit_events(created_at);
create index if not exists ix_order_owner on orders(owner_email);
